from taf.internal.aliasing import aliasing_scope
from taf.internal.rpc.pyro.pyro_rpc import PyroRPC
from taf.internal.rpc.pyro.proxy import PyroProxy
from taf.internal.rpc.pyro.robot_keywords.keywords import PYROKeyWords


class pyro(PYROKeyWords):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope(name=__name__, lookup_arg='proxy',
                                           lookup_type=PyroProxy)

    def __init__(self):
        super(pyro, self).__init__()
        self._rpc = PyroRPC()

    def configure(self, hostname, pyro_port, server_dir=None, username=None, password=None, python_path=None):
        """
        configure the remote server settings
        :param str hostname:    pyro hostname e.g. ip address
        :param int pyro_port:   port no the remote pyro server will listen on
        :param Optional[str] server_dir:  pyro working directory on remote pyro server
        :param Optional[str] username: username for ssh connection to the pc the remote pyro server will run on
        :param Optional[str] password: password for ssh connection to the pc the remote pyro server will run on
        :param Optional[str] python_path: python path in the remote server
        :return: None
        """
        self._rpc.configure(hostname, pyro_port, username, password, server_dir, python_path)

    def setup(self):
        """
        connect to remote pyro server via ssh and transfer required server file(s) to the remote pc
        then start the server
        :return: None
        :exception RequiredSoftwareMissing, ConnectFailedError
        """
        self._rpc.setup()

    def teardown(self):
        """
        if pyro server is still running will stop server first then disconnect ssh connection to the remote pc
        :return: None
        """
        self._rpc.teardown()

    def create_proxy(self, hostname=None, port=None, alias=None):
        """
        create proxy instance with  alias
        :param Optional[str] alias: proxy alias
        :return: taf.internal.rpc.pyro.proxy.PyroProxy
        """
        proxy = self._rpc.create_proxy(hostname=hostname, port=port)
        self.store.add(proxy, alias)
        return proxy

    @lookup_handler.implicit_lookup
    def run_shell_command(self, command, proxy=None):
        """
        execute shell command remotely
        :param str command: the command will be run remotely
        :param Optional[str] proxy: proxy alias
        :return: command output on shell
        """
        return proxy.run_shell_command(command)

    def _save_remote_files(self, target_dir):
        if self._rpc.workspace.is_accessable:
            self._rpc.workspace.collect_remote_files(self._rpc.workspace.log_dir, target_dir)
        else:
            self._rpc.workspace.setup()
            self._rpc.workspace.collect_remote_files(self._rpc.workspace.log_dir, target_dir)
            self._rpc.workspace.teardown()
